55	static bool mi_theap_page_is_valid(mi_theap_t* theap, mi_page_queue_t* pq, mi_page_t* page, void* arg1, void* arg2) {
56	  MI_UNUSED(arg1);
57	  MI_UNUSED(arg2);
58	  MI_UNUSED(pq);
59	  mi_assert_internal(mi_page_theap(page) == theap);
60	  mi_theap_t* const page_theap = _mi_heap_theap_peek(page->heap);
61	  mi_assert_internal(page_theap == NULL || theap == page_theap);
62	  mi_assert_expensive(_mi_page_is_valid(page));
63	  return true;
64	}
