117	void _mi_theap_merge_stats(mi_theap_t* theap) {
118	  mi_assert_internal(mi_theap_is_initialized(theap));
119	  mi_heap_t* const heap = _mi_theap_heap(theap);
120	  _mi_stats_merge_into(&heap->stats, &theap->stats);
121	}
122	
123	static void mi_theap_collect_ex(mi_theap_t* theap, mi_collect_t collect)
124	{
125	  if (theap==NULL || !mi_theap_is_initialized(theap)) return;
126	  mi_assert_expensive(mi_theap_is_valid(theap));
127	
128	  const bool force = (collect >= MI_FORCE);
129	  _mi_deferred_free(theap, force);
130	
131	  // python/cpython#112532: we may be called from a thread that is not the owner of the theap
132	  // const bool is_main_thread = (_mi_is_main_thread() && theap->thread_id == _mi_thread_id());
133	
134	  // collect retired pages (and full pages if theap->allow_page_abandon is false)
135	  _mi_theap_collect_retired(theap, force); 
136	
137	  // collect all pages owned by this thread
138	  mi_theap_visit_pages(theap, &mi_theap_page_collect, (collect!=MI_NORMAL), &collect, NULL);  // dont normally visit full pages, see issue #1220
139	
140	  // collect arenas (this is program wide so don't force purges on abandonment of threads)
141	  //mi_atomic_storei64_release(&theap->tld->subproc->purge_expire, 1);
142	  if (collect != MI_ABANDON) {
143	    _mi_arenas_collect(collect == MI_FORCE /* force purge? */, collect >= MI_FORCE /* visit all? */, theap->tld);
144	  }
145	
146	  // merge statistics
147	  _mi_theap_merge_stats(theap);
148	}
149	
150	void _mi_theap_collect_abandon(mi_theap_t* theap) {
151	  mi_theap_collect_ex(theap, MI_ABANDON);
152	}
153	
154	void mi_theap_collect(mi_theap_t* theap, bool force) mi_attr_noexcept {
155	  mi_theap_collect_ex(theap, (force ? MI_FORCE : MI_NORMAL));
156	}
