172	mi_theap_t* mi_theap_get_default(void) {
173	  mi_theap_t* theap = _mi_theap_default();
174	  if mi_unlikely(!mi_theap_is_initialized(theap)) {
175	    mi_thread_init();
176	    theap = _mi_theap_default();
177	    mi_assert_internal(mi_theap_is_initialized(theap));
178	  }
179	  return theap;
180	}
