235	// todo: make order of parameters consistent (but would that break compat with CPython?)
236	void _mi_theap_init(mi_theap_t* theap, mi_heap_t* heap, mi_tld_t* tld)
237	{
238	  mi_assert_internal(theap!=NULL);
239	  mi_assert_internal(heap!=NULL);
240	  mi_assert_internal(tld!=NULL);
241	  mi_memid_t memid = theap->memid;
242	  _mi_memcpy_aligned(theap, &_mi_theap_empty, sizeof(mi_theap_t));
243	  theap->memid = memid;
244	  theap->tld   = tld;  // avoid reading the thread-local tld during initialization
245	  mi_atomic_store_release(&theap->refcount,1);  
246	  mi_atomic_store_ptr_release(mi_subproc_t,&theap->subproc,heap->subproc);
247	  mi_assert_internal(theap->stats.size == sizeof(mi_stats_t));
248	  mi_theap_options_init(theap);
249	
250	  if (theap->tld->is_in_threadpool) {
251	    // if we run as part of a thread pool it is better to not arbitrarily reclaim abandoned pages into our theap.
252	    // this is checked in `free.c:mi_free_try_collect_mt`
253	    // .. but abandoning is good in this case: quarter the full page retain (possibly to 0)
254	    // (so blocked threads do not hold on to too much memory)
255	    if (theap->page_full_retain > 0) {
256	      theap->page_full_retain = theap->page_full_retain / 4;
257	    }
258	  }
259	
260	  // push on the thread local theaps list
261	  mi_theap_t* head = NULL;
262	  mi_random_ctx_t head_random;
263	  mi_lock(&theap->tld->theaps_lock) {
264	    head = theap->tld->theaps;
265	    theap->tprev = NULL;
266	    theap->tnext = head;
267	    theap->tld->theaps = theap;
268	    if (head!=NULL) { 
269	      head->tprev = theap; 
270	      head_random = head->random;
271	    }    
272	  }
273	
274	  // initialize random if heap==NULL
275	  if (head==NULL) {  // first theap of the first thread?
276	    #if defined(_WIN32) && !defined(MI_SHARED_LIB)
277	    if (tld->thread_seq==0) {
278	      _mi_random_init_weak(&theap->random);    // prevent allocation failure during bcrypt dll initialization with static linking (issue #1185)
279	    }
280	    else
281	    #endif
282	    {
283	      _mi_random_init(&theap->random);
284	    }
285	  }
286	  else {
287	    _mi_random_split(&head_random, &theap->random); // &theap->random is used as nonce so it is ok if threads capture the same head->random
288	  }
289	  theap->cookie = _mi_theap_random_next(theap) | 1;
290	  mi_theap_guarded_init(theap); // needs theap->random
291	  if (!theap->is_detached) {
292	    mi_subproc_stat_increase(_mi_theap_subproc(theap),theaps,1);  // on subproc to match theap_free_mem
293	  }
294	
295	  // only now set the heap member as it is used to determine if a theap is initialized
296	  mi_atomic_store_ptr_release(mi_heap_t,&theap->heap,heap);
297	  
298	  // push on the heap's theap list
299	  mi_lock(&heap->theaps_lock) {
300	    head = heap->theaps;
301	    theap->hprev = NULL;
302	    theap->hnext = head;
303	    if (head!=NULL) { head->hprev = theap; }
304	    heap->theaps = theap;
305	  }
306	}
