336	mi_theap_t* _mi_theap_create(mi_heap_t* heap, mi_tld_t* tld) {
337	  mi_theap_t* theap = _mi_theap_alloc(heap,tld);
338	  if (theap == NULL) return NULL;
339	  _mi_theap_init(theap, heap, tld);
340	  return theap;
341	}
