347	static void mi_theap_free_mem(mi_theap_t* theap) {
348	  if (theap!=NULL) {
349	    mi_subproc_t* const subproc = mi_atomic_load_ptr_relaxed(mi_subproc_t,&theap->subproc);      
350	    if (!theap->is_detached) {
351	      mi_subproc_stat_decrease(subproc,theaps,1);  
352	    }
353	    _mi_meta_free(subproc, theap, theap->memid);
354	  }
355	}
