357	// we need to reference count theaps due to the _mi_theap_cached thread locals
358	void _mi_theap_incref(mi_theap_t* theap) {
359	  if (theap!=NULL && !mi_memid_needs_no_free(theap->memid)) {
360	    mi_atomic_increment_acq_rel(&theap->refcount);
361	  }
362	}
363	
364	void _mi_theap_decref(mi_theap_t* theap) {
365	  if (theap!=NULL && !mi_memid_needs_no_free(theap->memid)) {
366	    if (mi_atomic_decrement_acq_rel(&theap->refcount) == 1) {
367	      mi_theap_free_mem(theap);
368	    }
369	  }
370	}
